Read the serial and price columns from Sheet2 using cached values. Sum prices for each serial and record the first row where each serial appears. Write the total only in C on those first rows and set the other C2:C11 cells to None.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet2"]
vws = vals["Sheet2"]

def norm_key(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return s
    return x

def to_num(x):
    if isinstance(x, bool):
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        try:
            return float(s)
        except ValueError:
            return 0.0
    return 0.0

# Scan enough rows to include the answer region and any actual data rows.
last = max(11, ws.max_row, vws.max_row)
if last > 100000:
    last = 100000

sums = {}
first = {}

for r in range(2, last + 1):
    key = norm_key(vws.cell(row=r, column=1).value)
    if key is None:
        continue
    if key not in first:
        first[key] = r
        sums[key] = 0.0
    sums[key] += to_num(vws.cell(row=r, column=2).value)

# Answer region is exactly Sheet2!C2:C11.
for r in range(2, 12):
    key = norm_key(vws.cell(row=r, column=1).value)
    if key is not None and first.get(key) == r:
        val = sums.get(key, 0.0)
        if abs(val) < 1e-12:
            val = 0.0
        ws.cell(row=r, column=3).value = val
    else:
        ws.cell(row=r, column=3).value = None

wb.save(OUT)

print("scanned rows:", last)
print("computed sums:", sums)
